-- One partial HNSW index per large perspective (ADR-0103, amendment of 2026-11-11). The largest
-- graph (Adventist, about 152,000 vectors) fits in 1 GB; the table refuses writes while it builds.
SET maintenance_work_mem = '1GB';--> statement-breakpoint
CREATE INDEX "library_passages_adventist_hnsw" ON "library_passages" USING hnsw ("embedding" halfvec_cosine_ops) WITH (m=16,ef_construction=64) WHERE (case when coalesce(tradition, '') = '' and jsonb_array_length(tags) = 0 then 'reference' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'adventiste' then 'adventist' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'catholi|thomiste|scolastique' then 'catholic' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'christianisme ancien|patristique' then 'patristic' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'judaisme|rabbinique' then 'jewish' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'orthodox' then 'orthodox' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'exegese critique|universitaire|moderniste' then 'academic' when translate(lower(coalesce(tradition, '') || ' ' || tags::text), 'àâäáãéèêëíìîïóòôöõúùûüçñÿ', 'aaaaaeeeeiiiiooooouuuucny') ~ 'dispensational|freres|evangelique|baptiste|restaurationniste|pentecot' then 'evangelical' else 'protestant' end) = 'adventist';--> statement-breakpoint
